// Bounded supplied-history lifecycle qualification; no performance timing claim.
#include "successor_gate.hpp"
#include "active_kv.hpp"
#include "frozen_reference_primitives.inc"
#include <map>
using namespace hs::n1chain;
static SuccessorGate* budget=nullptr;
static std::string output;
static int head(llama_context*c){auto m=llama_get_memory(c);int lo=llama_memory_seq_pos_min(m,0),hi=llama_memory_seq_pos_max(m,0);need(hi<0||lo==0,"noncontiguous native state");return hi<0?0:hi+1;}
static void js(const std::string&n,const PJ&j){durable(output+"/"+n,j.dump(2)+"\n");}
static void raw(const std::string&n,const void*p,size_t b){budget->bytes(b);durable(output+"/"+n,std::string(static_cast<const char*>(p),b));}
static std::vector<float> step(llama_context*c,const std::vector<int>&ids,int pos,const std::string&name){budget->rows(ids.size());need(head(c)==pos,"predecode native head");::decode(c,ids,pos,false);need(head(c)==pos+int(ids.size()),"partial decode");auto v=::logits(c,151936);for(float x:v)need(std::isfinite(x),"nonfinite full vector");raw(name+".f32",v.data(),v.size()*sizeof(float));js(name+".op.json",{{"request",budget->active()},{"input_ids",ids},{"position",pos},{"rows",ids.size()},{"physical_ubatch",1},{"output_mask","last only"},{"requested_vectors",1},{"actual_head",head(c)}});return v;}
static void snap(llama_context*c,const std::string&name){int h=head(c);std::string bytes;auto m=capture_active_kv(c,*budget,*budget,name,h,[&](const std::string&,int,const uint8_t*p,size_t n){for(size_t i=0;i<n;i+=2){uint16_t w;std::memcpy(&w,p+i,2);need((w&0x7c00)!=0x7c00,"nonfinite active F16 state");}bytes.append(reinterpret_cast<const char*>(p),n);});raw(name+".kv",bytes.data(),bytes.size());PJ tensors=PJ::array(),cells=PJ::array();for(auto&t:m.tensors)tensors.push_back({{"kind",t.kind},{"layer",t.layer},{"active_bytes",t.canonical_active_bytes},{"dimensions",t.dimensions},{"strides",t.byte_strides},{"physical_read_bytes",t.physical_read_bytes},{"callbacks",t.native_tensor_callbacks}});for(auto x:m.cells_physical_order)cells.push_back({x.physical,x.position,x.sequence});js(name+".json",{{"head",h},{"capacity",m.capacity},{"cells",cells},{"physical_by_position",m.physical_by_position},{"tensors",tensors},{"active_bytes",m.canonical_active_bytes},{"physical_read_bytes",m.physical_read_bytes},{"native_tensor_callbacks",m.native_tensor_callbacks},{"format",m.format}});}
static void reset(llama_context*c,const std::string&name){budget->before_mutation(name,"clear");llama_memory_clear(llama_get_memory(c),true);llama_synchronize(c);need(head(c)==0,"reset did not empty real context");js(name+".json",{{"head",0},{"pending",nullptr},{"frontier_valid",false},{"output_ownership","previous owned vectors remain separate; context reset invalidates borrowed frontier"}});}
int main(int argc,char**argv){try{
 need(argc==3&&hashfile(argv[1])==argv[2],"immutable job arguments");PJ j=PJ::parse(textfile(argv[1]));SuccessorGate gate(j);budget=&gate;output=j.at("output");auto manifest=PJ::parse(textfile(j.at("ledger_root").get<std::string>()+"/MANIFEST.json"));std::string role=j.at("role");need(role=="R"||role=="REPEAT"||role=="COLD","reference image role");
 // The pre-exec wrapper hashes the full original model through this retained FD.
 // Compare the exact descriptor stat both before/after loading; no slow O0 hash loop.
 int model_fd=j.at("model_fd");struct stat st{};auto model_stat=[&](){need(::fstat(model_fd,&st)==0,"retained model descriptor missing");auto b=j.at("model_stat");need(uint64_t(st.st_dev)==b.at("dev")&&uint64_t(st.st_ino)==b.at("ino")&&uint64_t(st.st_size)==b.at("size")&&int64_t(st.st_mtim.tv_sec)*1000000000+st.st_mtim.tv_nsec==b.at("mtime_ns").get<int64_t>()&&int64_t(st.st_ctim.tv_sec)*1000000000+st.st_ctim.tv_nsec==b.at("ctime_ns").get<int64_t>(),"model descriptor identity changed");};model_stat();
 gate.before_backend_init(role);ggml_time_init();llama_backend_init();ggml_backend_dev_t gpu=nullptr;for(size_t i=0;i<ggml_backend_dev_count();++i){auto d=ggml_backend_dev_get(i);if(ggml_backend_dev_type(d)==GGML_BACKEND_DEVICE_TYPE_GPU){need(!gpu,"multiple visible GPUs");gpu=d;}}need(gpu,"allocated GPU missing");ggml_backend_dev_t devices[]={gpu,nullptr};auto mp=llama_model_default_params();mp.devices=devices;mp.n_gpu_layers=999;mp.split_mode=LLAMA_SPLIT_MODE_NONE;gate.before_model_load(role);gate.before_placement(role);std::string model_path="/proc/self/fd/"+std::to_string(model_fd);std::unique_ptr<llama_model,ModelDelete>model(llama_model_load_from_file(model_path.c_str(),mp));need(bool(model),"model load failed");model_stat();auto vocab=llama_model_get_vocab(model.get());need(llama_vocab_n_tokens(vocab)==151936,"actual vocabulary identity");
 auto cp=llama_context_default_params();cp.n_ctx=4096;cp.n_batch=4096;cp.n_ubatch=1;cp.n_seq_max=1;cp.n_outputs_max=1;cp.n_outputs_max_per_seq=1;cp.n_threads=2;cp.n_threads_batch=2;cp.type_k=GGML_TYPE_F16;cp.type_v=GGML_TYPE_F16;cp.flash_attn_type=LLAMA_FLASH_ATTN_TYPE_DISABLED;
 gate.before_context(role);std::unique_ptr<llama_context,ContextDelete>ctx(llama_init_from_model(model.get(),cp));need(bool(ctx)&&llama_n_ctx(ctx.get())==4096&&llama_n_ubatch(ctx.get())==1&&head(ctx.get())==0,"actual reference configuration");auto c=ctx.get();js("CONFIG.json",{{"role",role},{"n_ctx",4096},{"n_ubatch",1},{"output_reserve",1},{"KV","F16"},{"threads",2},{"modules",linux_transfer::modules()},{"same_context_across_turns",true},{"source_kind","SUPPLIED_HISTORY_FIXED_CONTINUATION_NOT_FREE_GENERATION"}});
 for(auto&cs:manifest.at("cases")){
  std::string id=cs.at("id");auto q0=cs.at("initial_prompt_ids").get<std::vector<int>>(),body=cs.at("provided_assistant_ids").get<std::vector<int>>(),old=cs.at("old_materialized_ids").get<std::vector<int>>(),q=cs.at("canonical_next_ids").get<std::vector<int>>(),f=cs.at("fixed_continuation_ids").get<std::vector<int>>();int k=cs.at("predicted_retained_head"),pending=cs.at("pending");for(auto*x:{&q0,&body,&old,&q,&f})for(int t:*x)need(t>=0&&t<151936,"native token range");need(llama_vocab_is_eog(vocab,pending),"pending must match actual EOG");for(int t:f)need(!llama_vocab_is_eog(vocab,t),"fixed continuation includes EOG");need(head(c)==0&&q.size()+f.size()<=4096,"episode capacity/reset");
  if(role!="COLD"){
   gate.begin(role+"/"+id+"/INITIAL");auto owned=step(c,q0,0,id+"-initial-prompt");snap(c,id+"-initial-prompt-state");for(size_t i=0;i<body.size();++i)owned=step(c,{body[i]},q0.size()+i,id+"-body-"+std::to_string(i));need(head(c)==int(old.size()),"actual old materialized head");snap(c,id+"-old-state");auto borrowed=::logits(c,151936);need(owned.size()==borrowed.size()&&!std::memcmp(owned.data(),borrowed.data(),owned.size()*4),"owned frontier differs");js(id+"-old-frontier.json",{{"materialized_head",head(c)},{"logical_ids",cs.at("old_logical_ids")},{"pending",pending},{"frontier_valid",true},{"last_owned_output",id+"-body-"+std::to_string(body.size()-1)+".f32"}});gate.finish();
   gate.begin(role+"/"+id+"/APPEND");int lcp=0;while(lcp<std::min<int>(old.size(),q.size())&&old[lcp]==q[lcp])++lcp;need(lcp==k,"predicted/actual token LCP differs");gate.before_mutation(id,"trim");need(llama_memory_seq_rm(llama_get_memory(c),0,k,-1),"trim failed; stop, no hidden rebuild");llama_synchronize(c);need(head(c)==k,"native trim retained head differs");snap(c,id+"-trimmed-state");js(id+"-reconcile.json",{{"discarded_pending",pending},{"pending",nullptr},{"frontier_valid",false},{"retained_head",k},{"native_head",head(c)},{"canonical_input_unchanged",true}});
  }else{gate.begin(role+"/"+id+"/APPEND");step(c,std::vector<int>(q.begin(),q.begin()+k),0,id+"-cold-prefix");snap(c,id+"-trimmed-state");js(id+"-reconcile.json",{{"pending",nullptr},{"frontier_valid",false},{"retained_head",k},{"native_head",head(c)},{"cold_frontier_not_compared_at_invalid_resident_frontier",true}});}
  for(int p=k;p<int(q.size());++p)step(c,{q[p]},p,id+"-q-"+std::to_string(p));snap(c,id+"-Q-state");for(size_t i=0;i<f.size();++i){step(c,{f[i]},q.size()+i,id+"-f-"+std::to_string(i));snap(c,id+"-F-state-"+std::to_string(i));}js(id+"-final-frontier.json",{{"materialized_head",head(c)},{"pending",nullptr},{"frontier_valid",true},{"last_owned_output",id+"-f-7.f32"},{"continuation","fixed source tokens, not generated argmax"}});reset(c,id+"-reset");gate.finish();
 }
 gate.guard();model_stat();js("RESULT.json",{{"status","CAPTURE_COMPLETE_REQUIRES_INDEPENDENT_STRICT_COMPARISON"},{"role",role},{"consumed",gate.state().at("consumed")},{"requests",gate.state().at("requests")},{"performance",false},{"native261_promoted",false}});return 0;
 }catch(const std::exception&e){if(!output.empty()){try{js("STOP_NATIVE.json",{{"reason",e.what()},{"no_automatic_retry",true}});}catch(...){}}std::cerr<<"LIFECYCLE_STOP "<<e.what()<<'\n';return 74;}}
